contract InvMutTest {
    C c;
    address initialOwner;

    constructor(C _c) { c = _c; initialOwner = c.owner(); }

    // single public test entry; take an amount to forward to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // record observable state before the call
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // make the call and capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - The owner address must not change as a result of go()
        // - If the call succeeded then the contract's balance must be zero (it forwards received ETH out)
        // We allow balanceAfter > 0 only if the call reverted (then state may be unchanged)
        assert(ownerAfter == ownerBefore && (reverted || balanceAfter == 0));
    }

    // allow receiving ETH when C forwards to this contract
    receive() external payable {}
}

